import{c as e,o as a,a1 as r,de as s,df as l,dg as t,dh as n,di as p,dj as o,dk as i,dl as m}from"./chunks/framework.BRTUTj8f.js";/* empty css                                                                            */const d=r('<h1 id="vad-ar-rpg" tabindex="-1">Vad är RPG? <a class="header-anchor" href="#vad-ar-rpg" aria-label="Permalink to &quot;Vad är RPG?&quot;">​</a></h1><p><span class="a">RPG</span> står för <span class="a">Role-Playing Game</span> eller <span class="a">rollspel</span> på svenska. Det är en spelgenre där spelaren tar på sig en viss roll, ofta en karaktär i en fantasivärld eller ett äventyr, och utforskar världen, interagerar med andra karaktärer och utvecklar sin egen karaktär genom olika val och handlingar.</p><p><img src="'+s+'" alt=""></p><p>Rollspel finns i många varianter, både som <strong>bordsspel</strong>, <strong>datorspel</strong>, <strong>konsolspel</strong> och <strong>mobilspel</strong>, men alla RPG-spel har några gemensamma drag:</p><ol><li><p><span class="a">Karaktärsutveckling</span>: Spelaren får vanligtvis skapa och utveckla sin karaktär över tid genom att förbättra deras färdigheter, förmågor och attribut. Detta sker ofta genom erfarenhetspoäng som samlas när man utför uppdrag, besegrar fiender eller löser problem.</p></li><li><p><span class="a">Berättelse och världsbyggande</span>: RPG-spel är ofta fokuserade på en djup berättelse och en välutvecklad värld. Spelaren påverkas av, och påverkar, spelets händelser och världens tillstånd beroende på sina val och handlingar.</p></li><li><p><span class="a">Uppdrag och mål</span>: Spelaren följer ofta en serie uppdrag eller mål som kan vara relaterade till spelets huvudhandling eller sidouppdrag som ger extra erfarenhet eller resurser.</p></li><li><p><span class="a">Val och konsekvenser</span>: Många RPG-spel erbjuder möjligheter att göra val som påverkar spelets handling och resultat. Detta kan inkludera moraliska val, relationer med andra karaktärer eller beslut om vilka vägar man vill ta i berättelsen.</p></li><li><p><span class="a">Kampsystem</span>: De flesta RPG-spel har någon form av kampsystem, antingen i realtid eller turordningsbaserat. Spelaren kan behöva använda sina färdigheter och resurser taktiskt för att vinna strider och utmaningar.</p></li></ol><h2 id="exempel-pa-olika-typer-av-rpg-spel" tabindex="-1">Exempel på olika typer av RPG-spel: <a class="header-anchor" href="#exempel-pa-olika-typer-av-rpg-spel" aria-label="Permalink to &quot;Exempel på olika typer av RPG-spel:&quot;">​</a></h2><ul><li><p><span class="a">Tabletop RPGs (bordsspel):</span>:<br> Som <em><strong>Dungeons &amp; Dragons</strong></em>, där spelare samlas runt ett bord och spelar med tärningar, papper och penna, ledda av en spelledare som skapar världen och styr berättelsen.</p><p><img src="'+l+'" alt=""></p></li></ul><br><ul><li><p><span class="a">Singleplayer RPGs (ensamspel)</span>:<br> Som <em><strong>The Witcher 3</strong></em> och <em><strong>Skyrim</strong></em>, där spelaren följer en berättelse och utvecklar en karaktär i en rik, oftast öppen värld.</p><p><img src="'+t+'" alt=""></p><p><img src="'+n+'" alt=""></p></li></ul><br><ul><li><p><span class="a">MMORPGs (Massively Multiplayer Online RPGs)</span>:<br> Som <em><strong>World of Warcraft</strong></em> eller <em><strong>Final Fantasy XIV</strong></em>, där många spelare är online samtidigt i samma värld och kan samarbeta eller tävla med varandra.</p><p><img src="'+p+'" alt=""></p><p><img src="'+o+'" alt=""></p></li></ul><br><ul><li><p><span class="a">Action-RPGs</span>:<br> Som <em><strong>Diablo</strong></em>-serien eller <em><strong>Dark Souls</strong></em>, där spelet är mer fokuserat på snabba strider och skicklighetsbaserad spelstil men ändå innehåller RPG-element som karaktärsutveckling.</p><p><img src="'+i+'" alt=""></p><p><img src="'+m+'" alt=""></p></li></ul><br><p>RPG-spel är populära just för att de låter spelaren fördjupa sig i en annan värld, experimentera med olika roller och uppleva en berättelse från ett personligt perspektiv.</p>',15),g=[d],b=JSON.parse('{"title":"Vad är RPG?","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"programming1/rpg/what-is-rpg.md","filePath":"programming1/rpg/what-is-rpg.md"}'),c={name:"programming1/rpg/what-is-rpg.md"},f=Object.assign(c,{setup(h){return(k,v)=>(a(),e("div",null,g))}});export{b as __pageData,f as default};
